INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, 'math', 'g3', 'single', 2, '{"stem": "选择(1)：下列算式中，用划线标出“先算的步骤”，不正确的是 ( )。A. 100-75+25  B. 36-18+9  C. 72+8-9"}', 'B', 'B 不正确：纯加减运算应从左往右依次计算。36-18+9 划线在 18+9 上是错误的；A、C 同样从左往右', 'jsj3_sx_v94', '["jsj3_sx","U1","p006","choice_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1013, 'math', 'g3', 'single', 3, '{"stem": "选择(2)：一根绳子长 1000 米，第一次用去 372 米，第二次用去 484 米，现在绳子的长度比原来短了多少米？A. 1000-372-484  B. 1000-(372+484)  C. 372+484"}', 'C', '“短了多少米”是两次用去之和 372+484=856 米；A、B 算出的是剩下 144 米', 'jsj3_sx_v94', '["jsj3_sx","U1","p006","choice_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1011, 'math', 'g3', 'single', 2, '{"stem": "选择(3)：下列算式得数与 3+3+3+3+2 不相等的是 ( )。A. 3×4+2  B. 3×5-1  C. 3×2+4"}', 'C', '3+3+3+3+2=14；A 3×4+2=14 相等，B 3×5-1=14 相等，C 3×2+4=10 不相等', 'jsj3_sx_v94', '["jsj3_sx","U1","p006","choice_03"]', 1, NULL);
